<?php
declare(strict_types=1);
final class AuthController{
public static function register():void{if($_SERVER['REQUEST_METHOD']==='GET'){self::form(true);return;}verify_csrf();$email=strtolower(trim((string)($_POST['email']??'')));$pass=(string)($_POST['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10||strlen($pass)>200){flash('Informe e-mail válido e senha com pelo menos 10 caracteres.','error');redirect('/register');}$q=db()->prepare('SELECT id FROM users WHERE email=? LIMIT 1');$q->execute([$email]);if($q->fetch()){flash('Não foi possível criar a conta com esses dados.','error');redirect('/register');}$q=db()->prepare('INSERT INTO users(email,password_hash,created_at) VALUES(?,?,UTC_TIMESTAMP())');$q->execute([$email,password_hash($pass,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user_id']=(int)db()->lastInsertId();$_SESSION['user_email']=$email;redirect('/characters');}
public static function login():void{if($_SERVER['REQUEST_METHOD']==='GET'){self::form(false);return;}verify_csrf();$email=strtolower(trim((string)($_POST['email']??'')));$pass=(string)($_POST['password']??'');$q=db()->prepare('SELECT id,email,password_hash FROM users WHERE email=? LIMIT 1');$q->execute([$email]);$u=$q->fetch();if(!$u||!password_verify($pass,$u['password_hash'])){usleep(250000);flash('E-mail ou senha inválidos.','error');redirect('/login');}session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];$_SESSION['user_email']=$u['email'];redirect('/characters');}
public static function logout():void{verify_csrf();$_SESSION=[];if(ini_get('session.use_cookies')){$p=session_get_cookie_params();setcookie(session_name(),'',time()-42000,$p['path'],$p['domain']??'',(bool)$p['secure'],(bool)$p['httponly']);}session_destroy();redirect('/');}
private static function form(bool $reg):void{$f=consume_flash();ob_start();?><section class="auth"><div class="panel"><small>O CHAMADO DE AETHORIA</small><h1><?=$reg?'Comece sua jornada':'Retorne a Aethoria'?></h1><?php if($f):?><div class="notice error"><?=e($f['message'])?></div><?php endif;?><form method="post" class="stack"><?=csrf_field()?><label>E-mail<input type="email" name="email" maxlength="190" required></label><label>Senha<input type="password" name="password" minlength="10" maxlength="200" required></label><button class="button primary"><?=$reg?'Criar conta':'Entrar'?></button></form><p><?=$reg?'Já tem conta? <a href="/login">Entrar</a>':'Novo por aqui? <a href="/register">Criar conta</a>'?></p></div></section><?php render($reg?'Criar conta':'Entrar',(string)ob_get_clean());}
}
